SELECT category, brand, CASE WHEN brand IN ('Initech', 'Acme') THEN 'priority' ELSE 'other' END AS brand_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values, SUM(CASE WHEN category = 'Home' THEN price ELSE 0 END) AS home_price FROM products GROUP BY category, brand, CASE WHEN brand IN ('Initech', 'Acme') THEN 'priority' ELSE 'other' END ORDER BY brand_values ASC, brand DESC;
